begin;
create extension if not exists pgtap with schema extensions;
select plan(9);
insert into public.b2c_students(id,source_key,full_name) values ('41000000-0000-4000-8000-000000000001','test-b2c-validation','Kiểm tra');
insert into public.b2c_classes(id,program_slug,name) values ('41000000-0000-4000-8000-000000000002','tieng-anh','Lớp kiểm tra');
insert into public.b2c_enrollments(id,source_key,class_id,student_id) values ('41000000-0000-4000-8000-000000000003','test-b2c-validation','41000000-0000-4000-8000-000000000002','41000000-0000-4000-8000-000000000001');
select set_config('request.jwt.claims', json_build_object('sub', (select id from public.profiles where role in ('super_admin','academic_manager') and is_active limit 1), 'role','authenticated')::text, true);
set local role authenticated;
select throws_ok($$select public.update_b2c_enrollment('41000000-0000-4000-8000-000000000003','123','Sale','2026-10-13','tieng-anh','studying')$$, '22023', null, 'Chặn SĐT sai');
select throws_ok($$select public.update_b2c_enrollment('41000000-0000-4000-8000-000000000003','0912345678',' ','2026-10-13','tieng-anh','studying')$$, '22023', null, 'Bắt buộc người chốt');
select throws_ok($$select public.update_b2c_enrollment('41000000-0000-4000-8000-000000000003','0912345678','Sale',null,'tieng-anh','studying')$$, '22023', null, 'Bắt buộc ngày nhập học');
select throws_ok($$select public.update_b2c_enrollment('41000000-0000-4000-8000-000000000003','0912345678','Sale','2026-10-13',null,'studying')$$, '22023', null, 'Bắt buộc chương trình');
select throws_ok($$select public.update_b2c_enrollment('41000000-0000-4000-8000-000000000003','0912345678','Sale','2026-10-13','tieng-anh','studying','2026-10-13','2026-10-12')$$, '22023', null, 'Chặn thứ tự ngày sai');
select throws_ok($$select public.update_b2c_enrollment('41000000-0000-4000-8000-000000000003','0912345678','Sale','2026-10-13','lop-ve','studying')$$, '22023', null, 'Không giả mạo chương trình của lớp');
select lives_ok($$select public.update_b2c_enrollment('41000000-0000-4000-8000-000000000003','0912345678','Sale','2026-10-13','tieng-anh','studying','2026-10-13','2026-10-13')$$, 'Lưu hợp lệ với ngày bằng nhau');
select is((select phone from public.b2c_students where source_key='test-b2c-validation'), '0912345678', 'SĐT lưu trong hồ sơ');
select set_config('request.jwt.claims','{"role":"authenticated"}',true);
select throws_ok($$select public.update_b2c_enrollment('41000000-0000-4000-8000-000000000003','0912345678','Sale','2026-10-13','tieng-anh','studying')$$, '42501', null, 'Thiếu quyền manager bị chặn');
select * from finish();
rollback;
